#include <bits/stdc++.h>
using namespace std;

long long C(int n, int r, int mod, vector<long long>& fact, vector<long long>& inv_fact) {
    if (n < 0 || r < 0 || r > n) return 0;
    return fact[n] * inv_fact[r] % mod * inv_fact[n - r] % mod;
}

long long pow_mod(long long a, int n, int mod) {
    long long result = 1;
    long long base = a % mod;
    while (n > 0) {
        if (n & 1) result = result * base % mod;
        base = base * base % mod;
        n >>= 1;
    }
    return result;
}

void enumFIF(int n, int mod, vector<long long>& fact, vector<long long>& inv_fact) {
    fact.resize(n + 1);
    inv_fact.resize(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = fact[i - 1] * i % mod;
    }
    long long a = fact[n];
    long long b = mod;
    long long p = 1, q = 0;
    while (b > 0) {
        long long c = a / b;
        long long d = a;
        a = b;
        b = d % b;
        d = p;
        p = q;
        q = d - c * q;
    }
    inv_fact[n] = p < 0 ? p + mod : p;
    for (int i = n - 1; i >= 0; i--) {
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % mod;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, K, L;
    cin >> n >> K >> L;
    int mod = 998244353;
    vector<long long> fact, inv_fact;
    enumFIF(10000, mod, fact, inv_fact);
    vector<long long> muls(n + 1, 0);
    for (int i = K; i <= n; i++) {
        long long m = C(n, i, mod, fact, inv_fact);
        for (int j = i; j <= n; j++) {
            long long sign = ((j - i) % 2 == 0) ? 1 : -1;
            long long val = m * C(n - i, n - j, mod, fact, inv_fact) % mod * sign;
            muls[j] = (muls[j] + val) % mod;
        }
    }
    long long ans = 0;
    for (int i = K; i <= n; i++) {
        long long term = pow_mod(2, i, mod) * fact[i] % mod * fact[i] % mod
                * fact[2 * i + 1] % mod * muls[i] % mod;
        ans = (ans + term) % mod;
    }
    if (ans < 0) ans += mod;
    cout << (ans * L) % mod << "\n";
    return 0;
}

